import { Schema, model, type Document as MongooseDocument, type Model, type Types } from "mongoose";
import { USER_ROLES, type UserRole } from "../constants/roles";
import { DOCUMENT_CATEGORIES, type DocumentCategory } from "../constants/collaboration";

/**
 * Metadata for a file stored on disk in backend/uploads.
 * The stored filename is generated by the server; the original name is only
 * used for display and the download prompt.
 */
export interface IDocument extends MongooseDocument {
  title: string;
  description?: string;
  fileName: string;
  storedName: string;
  mimeType: string;
  size: number;
  category: DocumentCategory;
  deal?: Types.ObjectId;
  uploadedBy: Types.ObjectId;
  visibleTo: UserRole[];
  createdAt: Date;
  updatedAt: Date;
}

type DocumentModel = Model<IDocument>;

const documentSchema = new Schema<IDocument, DocumentModel>(
  {
    title: { type: String, required: true, trim: true, maxlength: 160 },
    description: { type: String, trim: true, maxlength: 1000 },
    fileName: { type: String, required: true, trim: true },
    storedName: { type: String, required: true, unique: true, trim: true },
    mimeType: { type: String, required: true, trim: true },
    size: { type: Number, required: true, min: 0 },
    category: { type: String, enum: DOCUMENT_CATEGORIES, default: "other" },
    deal: { type: Schema.Types.ObjectId, ref: "Deal" },
    uploadedBy: { type: Schema.Types.ObjectId, ref: "User", required: true },
    visibleTo: {
      type: [{ type: String, enum: USER_ROLES }],
      default: ["admin", "advisor"],
    },
  },
  { timestamps: true },
);

documentSchema.index({ deal: 1, createdAt: -1 });
documentSchema.index({ uploadedBy: 1, createdAt: -1 });
documentSchema.index({ visibleTo: 1, createdAt: -1 });

export const DocumentFile = model<IDocument, DocumentModel>("Document", documentSchema);
